"""Independent brute-force reference implementation (slow, obviously correct)."""
import itertools
import operator

OPS = {'eq': operator.eq, 'ne': operator.ne, 'lt': operator.lt,
       'le': operator.le, 'gt': operator.gt, 'ge': operator.ge}


def compile_job(job):
    fields = job['fields']
    nf = len(fields)
    K = job['slots']
    fpos = {f['name']: i for i, f in enumerate(fields)}
    domains = [f['domain'] for f in fields]
    ncells = K * nf

    def cellidx(ref):
        return ref[0] * nf + fpos[ref[1]]

    def termval(term, cells):
        if 'const' in term:
            return term['const']
        if 'sum' in term:
            return sum(cells[cellidx(r)] for r in term['sum'])
        v = cells[cellidx(term['ref'])]
        if 'scale' in term:
            return v * term['scale']
        return v

    def predval(p, cells):
        if p['kind'] == 'cmp':
            return OPS[p['op']](termval(p['left'], cells), termval(p['right'], cells))
        idx = fpos[p['field']]
        vals = [cells[s * nf + idx] for s in range(K)]
        f = OPS[p['op']]
        if p['kind'] == 'any':
            return any(f(v, p['value']) for v in vals)
        return all(f(v, p['value']) for v in vals)

    # universe in lexicographic order of flattened cells (cell 0 most significant)
    universe = [list(w) for w in itertools.product(*[domains[c % nf] for c in range(ncells)])]
    U = len(universe)
    utruth = [[predval(p, w) for p in job['predicates']] for w in universe]
    train = [list(itertools.chain.from_iterable(w)) for w in job['train']]
    n = len(train)
    ttruth = [[predval(p, w) for p in job['predicates']] for w in train]
    P = len(job['predicates'])
    width = job['width']

    rules = []
    for size in range(1, width + 1):
        for clause in itertools.combinations(range(P), size):
            # condition 1: every training window satisfies the clause
            if not all(any(ttruth[w][l] for l in clause) for w in range(n)):
                continue
            # condition 2 + witnesses
            wit = []
            good = True
            for l in clause:
                others = [j for j in clause if j != l]
                idx = None
                for w in range(n):
                    if ttruth[w][l] and all(not ttruth[w][j] for j in others):
                        idx = w
                        break
                if idx is None:
                    good = False
                    break
                wit.append(idx)
            if not good:
                continue
            # condition 3: some universe window falsifies the clause
            ce = None
            for u in range(U):
                if not any(utruth[u][l] for l in clause):
                    ce = u
                    break
            if ce is None:
                continue
            rules.append({'clause': list(clause), 'witnesses': wit, 'counterexample': ce})
    rules.sort(key=lambda r: (len(r['clause']), r['clause']))

    approved = {tuple(a) for a in job['approved']}
    active = [list(r['clause']) for r in rules if tuple(r['clause']) in approved]

    answers = []
    for q in job['queries']:
        fixed = {cellidx(b['ref']): b['value'] for b in q['fixed']}
        tcell = cellidx(q['target'])
        prefix = q['prefix']
        completions = []
        for u in range(U):
            ok = True
            for c in active:
                if not any(utruth[u][l] for l in c):
                    ok = False
                    break
            if not ok:
                continue
            if any(universe[u][c] != v for c, v in fixed.items()):
                continue
            if not str(universe[u][tcell]).startswith(prefix):
                continue
            completions.append(u)
        tokens = []
        for d in '0123456789':
            if any(str(universe[u][tcell]).startswith(prefix + d) for u in completions):
                tokens.append(d)
        if any(str(universe[u][tcell]) == prefix for u in completions):
            tokens.append('END')
        answers.append({'count': len(completions), 'tokens': tokens,
                        'witness': min(completions) if completions else None})
    return {'rules': rules, 'active': active, 'answers': answers}
